content.text:
{
  "name": "TOPTICA iBeam 激光器",
  "name_en": "TOPTICA iBeam Laser",
  "manufacturer": "TOPTICA",
  "description": "用于实验室光学实验的可控激光光源，可进行激光开关和输出功率设置/读取，适合显微成像、激发照明等场景。",
  "description_en": "A controllable laser light source for laboratory optical experiments, supporting laser emission on/off control and output power set/readback. It is suitable for applications such as microscopy and excitation illumination.",
  "actions": [
    {
      "action_name": "auto-IsOn",
      "description": "获取激光发射是否开启。",
      "description_en": "Get whether laser emission is on."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "开启激光发射。",
      "description_en": "Turn on laser emission."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭激光发射。",
      "description_en": "Turn off laser emission."
    },
    {
      "action_name": "auto-SetPower",
      "description": "设置激光输出功率。",
      "description_en": "Set the laser output power."
    },
    {
      "action_name": "auto-GetPower",
      "description": "读取激光输出功率。",
      "description_en": "Read the laser output power."
    }
  ],
  "tag_hints": [
    "laser source",
    "laser power control",
    "emission on/off",
    "optical excitation",
    "microscopy illumination",
    "serial-controlled laser"
  ]
}

